mapper.select:
SELECT COUNT(*) FROM comments
WHERE blog_id = #{blogId}
  AND parent_id IS NULL

      AND status = #{status}

SELECT c.comment_id, c.blog_id, 'Blog #' || c.blog_id AS blog_title, c.user_id, u.username, u.email, c.content, c.like_count, c.ip_address, c.status, c.created_at FROM comments c JOIN users u ON c.user_id = u.user_id
AND (c.content ILIKE '%' || #{keyword} || '%' OR u.username ILIKE '%' || #{keyword} || '%' OR u.email ILIKE '%' || #{keyword} || '%')
AND c.status = #{status}
AND c.blog_id = #{blogId}::bigint
ORDER BY c.created_at DESC LIMIT #{limit} OFFSET #{offset}
